const LOGO="img/logo.webp";
/* ---------------- aparelhos ---------------- */
const DEVICES=[
  {id:"se",name:"iPhone SE",w:375,h:667,r:46,sr:4,sb:20,hb:0,kind:"classic"},
  {id:"ip15",name:"iPhone 15",w:393,h:852,r:58,sr:48,sb:54,hb:28,kind:"island"},
  {id:"ip15pm",name:"iPhone 15 Pro Max",w:430,h:932,r:62,sr:52,sb:54,hb:28,kind:"island"},
  {id:"pixel",name:"Pixel 8",w:412,h:915,r:46,sr:36,sb:40,hb:16,kind:"punch"},
  {id:"galaxy",name:"Galaxy A (comum)",w:360,h:800,r:40,sr:30,sb:36,hb:16,kind:"punch"},
  {id:"ipad",name:"iPad mini (tablet)",w:744,h:1133,r:40,sr:22,sb:28,hb:18,kind:"tablet"},
];
const ZOOMS=[{id:"fit",name:"Ajustar à janela"},{id:"1",name:"Tamanho real (100%)"},{id:"0.75",name:"75%"}];
let dev=DEVICES[1], zoom="fit";
try{const s=localStorage.getItem("proto-dev");if(s)dev=DEVICES.find(d=>d.id===s)||dev;zoom=localStorage.getItem("proto-zoom")||zoom}catch(e){}

const $=s=>document.querySelector(s);
function renderBench(){
  $("#devs").innerHTML=DEVICES.map(d=>`<button class="${d.id===dev.id?'on':''}" data-dev="${d.id}"><span>${d.name}</span><small>${d.w}×${d.h}</small></button>`).join("");
  $("#zoom").innerHTML=ZOOMS.map(z=>`<button class="${z.id===zoom?'on':''}" data-zoom="${z.id}"><span>${z.name}</span></button>`).join("");
  const D=$("#device"),SC=$("#screen");
  D.className="device"+(dev.kind==="classic"?" classic":"");
  D.style.setProperty("--r",dev.r+"px");SC.style.setProperty("--sr",dev.sr+"px");
  SC.style.width=dev.w+"px";SC.style.height=dev.h+"px";
  D.querySelectorAll(".island,.punch,.speaker,.homebtn").forEach(e=>e.remove());
  if(dev.kind==="island")D.insertAdjacentHTML("afterbegin",'<div class="island"></div>');
  if(dev.kind==="punch")D.insertAdjacentHTML("afterbegin",'<div class="punch"></div>');
  if(dev.kind==="classic")D.insertAdjacentHTML("afterbegin",'<div class="speaker"></div><div class="homebtn"></div>');
  const app=$("#app");
  if(isPhone()){app.style.setProperty("--sb","env(safe-area-inset-top,0px)");app.style.setProperty("--hb","env(safe-area-inset-bottom,0px)")}
  else{app.style.setProperty("--sb",dev.sb+"px");app.style.setProperty("--hb",dev.hb+"px")}
  fit();
}
function isPhone(){return innerWidth<=640||matchMedia("(display-mode: standalone)").matches||(matchMedia("(pointer: coarse)").matches&&!matchMedia("(hover: hover)").matches)}
function fit(){
  const st=$("#stage"),D=$("#device"),sc=$("#scaler");
  if(isPhone()!==fit.ph){fit.ph=isPhone();document.body.classList.toggle("full",fit.ph);renderBench();return}
  if(fit.ph){sc.style.transform="none";return}
  const fw=D.offsetWidth,fh=D.offsetHeight;
  let k=zoom==="fit"?Math.min((st.clientWidth-48)/fw,(st.clientHeight-70)/fh,1):parseFloat(zoom);
  sc.style.width=fw+"px";sc.style.height=fh+"px";sc.style.transform=`scale(${k})`;
  $("#dims").textContent=`${dev.name} · ${dev.w}×${dev.h} pontos · ${Math.round(k*100)}%`;
}
addEventListener("resize",fit);
document.addEventListener("click",e=>{
  const b=e.target.closest("[data-dev],[data-zoom]");if(!b)return;
  if(b.dataset.dev){dev=DEVICES.find(d=>d.id===b.dataset.dev);try{localStorage.setItem("proto-dev",dev.id)}catch(e){}}
  if(b.dataset.zoom){zoom=b.dataset.zoom;try{localStorage.setItem("proto-zoom",zoom)}catch(e){}}
  renderBench();
});

