function vFicha(){
  const k=S.ficha,f=FICHAS[k];
  return `${sbar(true)}<div class="abar"><div class="wrap"><button class="icbtn" data-go="fichas" aria-label="Voltar">${ic("back")}</button><div style="flex:1"><div class="sub">Ficha ${k}</div><h1 contenteditable="true" spellcheck="false" data-foco="${k}" style="outline:none">${f.foco}</h1></div><button class="icbtn" data-act="delficha" aria-label="Apagar ficha">${ic("trash")}</button></div></div>
  ${S.flow?`<div class="flowbar"><span class="sp">Montando suas fichas</span><span class="lt">${ORDER.map(x=>`<span class="${x===k?'on':FICHAS[x].ex.length?'ok':''}">${x}</span>`).join("")}</span></div>`:""}
  <div class="scroll"><div class="wrap" style="padding-top:16px;padding-bottom:20px">
  ${S.flow&&!f.ex.length?`<p class="muted" style="margin:0 0 12px;font-size:14.5px">Toque em <b>Adicionar exercício</b>. Os grupos que você escolheu para a ficha ${k} aparecem primeiro no catálogo.</p>`:""}
  ${f.ex.map((e,i)=>`<div class="edit-ex"><div class="top"><span class="muted" style="font-weight:800;width:18px">${i+1}</span><b style="cursor:pointer" data-how="${e.n}">${e.n}</b>
    <button class="mini" data-mv="${i}.-1" ${i?'':'disabled'} aria-label="Subir">${ic("up")}</button><button class="mini" data-mv="${i}.1" ${i<f.ex.length-1?'':'disabled'} aria-label="Descer">${ic("down")}</button><button class="mini del" data-rm="${i}" aria-label="Apagar">${ic("trash")}</button></div>
    <div class="steps">${[["s","Séries",1],["r","Reps",1],["d","Descanso",15]].map(([p,l,st])=>`<div class="step"><small>${l}</small><div class="ctl"><button data-stp="${i}.${p}.-${st}">−</button><b>${e[p]}${p==='d'?'s':''}</b><button data-stp="${i}.${p}.${st}">+</button></div></div>`).join("")}</div></div>`).join("")}
  <button class="btn line" data-act="add">${ic("plus")} Adicionar exercício</button>
  ${S.flow?(ORDER.indexOf(k)<ORDER.length-1?`<button class="btn red" style="margin-top:10px" data-act="flownext">Próxima: ficha ${ORDER[ORDER.indexOf(k)+1]} →</button>`:`<button class="btn red" style="margin-top:10px" data-act="flowdone">Concluir e ir para Hoje</button>`):`<button class="btn red" style="margin-top:10px" data-act="saveficha">Salvar ficha</button>`}
  </div></div>${nav()}${sheets()}`;
}
function vHist(){
  let body="";
  if(S.histTab==="lista")body=HIST.length?HIST.map(h=>`<div class="hist"><div class="d"><b>${new Date(h.at).getDate()}</b><small>${DW[new Date(h.at).getDay()]}</small></div><span class="tag">${h.f}</span><div class="i"><b>${FICHAS[h.f]?FICHAS[h.f].foco:"Ficha "+h.f}</b><small>${dm(h.at)} · ${h.min} min · ${h.s} séries${h.vol?" · "+h.vol.toLocaleString("pt-BR")+" kg":""}</small></div></div>`).join(""):`<p class="muted" style="text-align:center;padding:34px 10px">Seus treinos salvos aparecem aqui.</p>`;
  else{calcEvo();const ks=Object.keys(EVO);if(!ks.length)body=`<p class="muted" style="text-align:center;padding:34px 10px">A evolução de carga aparece depois do primeiro treino salvo com carga.</p>`;
    else{if(!EVO[S.evo])S.evo=ks[0];const v=EVO[S.evo],ga=v[v.length-1]-v[0],pc=v[0]?Math.round(ga/v[0]*100):0;
    body=`<div class="pills" style="margin-top:16px">${ks.map(n=>`<button class="${n===S.evo?'on':''}" data-evo="${n}">${n}</button>`).join("")}</div>
    <div class="card" style="margin-top:12px;padding:14px 10px 8px">${v.length>1?chart(v,EVO_D[S.evo]):`<p class="muted" style="text-align:center;margin:20px 0">Faça mais um treino com este exercício para ver a curva.</p>`}</div>
    <div class="kpi"><div><b>${v[v.length-1]} kg</b><span>carga atual</span></div><div><b class="up">${ga>=0?"+":""}${ga} kg</b><span>${ga>=0?"+":""}${pc}% em ${v.length} ${v.length===1?"treino":"treinos"}</span></div></div>`}}
  return `${sbar(true)}<div class="abar"><div class="wrap" style="display:block"><h1>Histórico</h1><div class="seg"><button class="${S.histTab==='lista'?'on':''}" data-ht="lista">Treinos</button><button class="${S.histTab==='evo'?'on':''}" data-ht="evo">Evolução</button></div></div></div>
  <div class="scroll"><div class="wrap" style="padding-bottom:20px">${body}</div></div>${nav()}`;
}
function chart(v,D){
  const W=340,H=190,p={l:34,r:12,t:14,b:26},mn=Math.floor(Math.min(...v)*0.9/5)*5;let mx=Math.ceil(Math.max(...v)*1.05/5)*5;if(mx<=mn)mx=mn+5;
  const x=i=>p.l+i*(W-p.l-p.r)/(v.length-1),y=val=>p.t+(1-(val-mn)/(mx-mn))*(H-p.t-p.b);
  const ticks=[mn,Math.round((mn+mx)/2),mx];
  const path=v.map((val,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(val).toFixed(1)}`).join("");
  const area=path+`L${x(v.length-1)},${H-p.b}L${x(0)},${H-p.b}Z`;
  return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Evolução de carga">
   ${ticks.map(t=>`<line x1="${p.l}" x2="${W-p.r}" y1="${y(t)}" y2="${y(t)}" stroke="#e8eaef"/><text x="${p.l-6}" y="${y(t)+4}" text-anchor="end" font-size="11" fill="#8a92a3">${t}</text>`).join("")}
   <path d="${area}" fill="#3A507A" opacity=".08"/><path d="${path}" fill="none" stroke="#3A507A" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>
   ${v.map((val,i)=>`<circle cx="${x(i)}" cy="${y(val)}" r="${i===v.length-1?5:3.5}" fill="${i===v.length-1?'#CE372E':'#3A507A'}" stroke="#fff" stroke-width="1.5"><title>${D[i]}: ${val} kg</title></circle>`).join("")}
   ${[...new Set([0,Math.floor((v.length-1)/2),v.length-1])].map(i=>`<text x="${x(i)}" y="${H-6}" text-anchor="middle" font-size="11" fill="#8a92a3">${D[i]}</text>`).join("")}
  </svg>`;
}
