function admFiltered(){const q=S.admQ.trim().toLowerCase();return S.admRows.filter(p=>!q||(p.nome||"").toLowerCase().includes(q))}
function admRows(){
  if(S.admLoading)return `<p class="muted" style="text-align:center;padding:30px 0">Carregando…</p>`;
  const rows=admFiltered();
  if(!rows.length)return `<p class="muted" style="text-align:center;padding:30px 0">Nenhum registro.</p>`;
  return rows.map(p=>{const dep=p.vinculo==="dependente",nm=((p.posto&&p.posto.toLowerCase()!=="civil"?p.posto+" ":"")+(p.nome||"Sem cadastro"));
    return `<div class="adm-row"><b>${esc(nm)}<span class="badge ${dep?'dep':''}">${dep?'Dep.':'Sócio'}</span>${p.saida?(p.saida_auto?'<span class="badge auto">Saída automática</span>':''):'<span class="badge now">Na academia</span>'}${p.relogio_divergente?'<span class="badge auto">Horário do celular</span>':''}</b><span class="tm">${hm(p.entrada)} → ${p.saida?hm(p.saida):"··:··"}</span><small>${dep&&p.titular?'Dependente de '+esc(p.titular)+' · ':''}${diaCurto(p.entrada)}</small><small style="text-align:right">${p.saida?durMin(Math.round((new Date(p.saida)-new Date(p.entrada))/60000)):"em andamento"}</small></div>`}).join("");
}
function durMin(m){return m>=60?`${Math.floor(m/60)}h${String(m%60).padStart(2,"0")}`:`${m} min`}
function dur(a,b){const [h1,m1]=a.split(":").map(Number),[h2,m2]=b.split(":").map(Number),m=((h2*60+m2)-(h1*60+m1)+1440)%1440;return m>=60?`${Math.floor(m/60)}h${String(m%60).padStart(2,"0")}`:`${m} min`}
