const fmt=s=>{s=Math.max(0,Math.floor(s));return `${String(Math.floor(s/60)).padStart(2,"0")}:${String(s%60).padStart(2,"0")}`};

/* bip + vibração no fim do descanso */
function beep(){if(!S.notif)return;try{navigator.vibrate&&navigator.vibrate([200,100,200])}catch(e){}
  try{const c=new (window.AudioContext||window.webkitAudioContext)();[0,.25].forEach(t=>{const o=c.createOscillator(),g=c.createGain();o.frequency.value=880;o.connect(g);g.connect(c.destination);g.gain.setValueAtTime(.2,c.currentTime+t);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+t+.2);o.start(c.currentTime+t);o.stop(c.currentTime+t+.22)})}catch(e){}}

setInterval(()=>{
  if(S.screen!=="treino"||!S.w)return;
  const c=$("#clk");if(c)c.textContent=fmt((Date.now()-S.w.t0)/1000);
  if(S.tmr&&S.tmr.paused==null){const left=tmrLeft();
    if(left===0&&!S.tmr.rang){S.tmr.rang=true;beep();render();return}
    const t=$("#tt"),a=$("#tarc");if(t&&left>0){t.textContent=fmt(left);const C=2*Math.PI*84;a.setAttribute("stroke-dashoffset",C*(1-left/S.tmr.total))}}
  if(S.rest){const left=Math.max(0,Math.ceil((S.rest.end-Date.now())/1000));
    if(left===0&&!S.rest.rang){S.rest.rang=true;beep();render();return}
    const t=$("#rt"),a=$("#arc");if(t&&left>0){t.textContent=fmt(left);const C=2*Math.PI*84;a.setAttribute("stroke-dashoffset",C*(1-left/S.rest.total))}}
},250);

