/* arrastar peças do rodízio */
let DR=null;
document.addEventListener("pointerdown",e=>{const pc=e.target.closest(".pc");if(!pc)return;const wrap=pc.parentElement,pcs=[...wrap.children];
  DR={pc,wrap,id:wrap.dataset.puz,from:pcs.indexOf(pc),x0:e.clientX,w:pc.getBoundingClientRect().width+6,scale:pc.getBoundingClientRect().width/pc.offsetWidth};pc.classList.add("drag");try{pc.setPointerCapture(e.pointerId)}catch(_){}});
document.addEventListener("pointermove",e=>{if(!DR)return;const dx=(e.clientX-DR.x0)/DR.scale;DR.pc.style.transform=`translateX(${dx}px) scale(1.06)`;DR.dx=dx});
document.addEventListener("pointerup",e=>{if(!DR)return;const d=DR;DR=null;d.pc.classList.remove("drag");d.pc.style.transform="";
  const arr=d.id==="order"?ORDER:S.seqDraft;let to=Math.max(0,Math.min(arr.length-1,d.from+Math.round((d.dx||0)/(d.w/d.scale))));
  if(to!==d.from){const [k]=arr.splice(d.from,1);arr.splice(to,0,k);if(d.id==="order"){S.today=sug()}render();if(d.id==="order")toast("Sequência: "+ORDER.join(" → "))}});
document.addEventListener("pointercancel",()=>{if(DR){DR.pc.classList.remove("drag");DR.pc.style.transform="";DR=null}});

/* ---------------- interações do app ---------------- */
$("#app").addEventListener("click",e=>{
  if(e.target.classList.contains("dim")){if(e.target.dataset.dim==="notaclose")S.nota=null;else if(e.target.dataset.dim==="restclose")S.rest=null;else if(e.target.dataset.dim==="seq")A.seqkeep();else if(e.target.dataset.dim==="how"){S.sheet=null}else S.sheet=null;render();return}
  const t=e.target.closest("[data-go],[data-act],[data-today],[data-open],[data-set],[data-ficha],[data-mv],[data-rm],[data-stp],[data-addex],[data-ht],[data-evo],[data-day],[data-how],[data-mus],[data-asst],[data-detg],[data-asstgo],[data-exdone],[data-tmr],[data-edx],[data-sdot]");if(!t)return;
  const d=t.dataset;
  if(d.go){if(d.go==="fichas"&&S.screen==="ficha"){}go(d.go);return}
  if(d.today){S.today=d.today;render();return}
  if(d.open!==undefined){S.openEx=S.openEx==+d.open?-1:+d.open;render();return}
  if(d.sdot){const [i,j]=d.sdot.split(".").map(Number),x=S.w.ex[i].sets[j];x.done=!x.done;
    if(x.done&&S.w.ex.every(e=>e.sets.every(y=>y.done)))S.sheet="finish";render();return}
  if(d.edx){const e=S.w.ex[+d.edx];S.edx={i:+d.edx,s:e.sets.length,r:e.r,kg:e.kg};render();return}
  if(d.tmr){const i=+d.tmr,e=S.w.ex[i],j=Math.max(0,e.sets.findIndex(x=>!x.done));if(e.sets.every(x=>x.done))e.sets.forEach(x=>x.done=false);S.rest=null;S.tmr={i,j,total:e.r*60,end:Date.now()+e.r*60000,paused:null};render();return}
  if(d.exdone){const ex=S.w.ex[+d.exdone],v=!ex.sets.every(s=>s.done);ex.sets.forEach(s=>s.done=v);
    if(v&&S.w.ex.every(e=>e.sets.every(s=>s.done)))S.sheet="finish";render();return}
  if(d.set){const [i,j]=d.set.split(".").map(Number),ex=S.w.ex[i],s=ex.sets[j];s.done=!s.done;
    if(s.done){const nextSet=ex.sets.findIndex(x=>!x.done);let next="";
      if(nextSet>=0)next=`Próxima: ${ex.n}, série ${nextSet+1}`;else{const ni=S.w.ex.findIndex(x=>x.sets.some(y=>!y.done));if(ni>=0){next=`Próximo exercício: ${S.w.ex[ni].n}`;S.openEx=ni}}
      if(nextSet>=0||next)S.rest={end:Date.now()+ex.d*1000,total:ex.d,next};
      if(!next)S.sheet="finish"}
    render();return}
  if(d.ficha){S.ficha=d.ficha;go("ficha");return}
  if(d.mv){const [i,dir]=d.mv.split(".").map(Number),a=FICHAS[S.ficha].ex;[a[i],a[i+dir]]=[a[i+dir],a[i]];render();return}
  if(d.rm){FICHAS[S.ficha].ex.splice(+d.rm,1);render();return}
  if(d.stp){const [i,p,st]=d.stp.split(".");const e2=FICHAS[S.ficha].ex[+i];e2[p]=Math.max(p==="d"?15:1,e2[p]+(+st));render();return}
  if(d.addex){FICHAS[S.ficha].ex.push(ex(d.addex,3,12,KG0[d.addex]??10,60));S.sheet=null;render();toast("Exercício adicionado");return}
  if(d.ht){S.histTab=d.ht;render();return}
  if(d.day){S.admDay=d.day;loadAdmin();return}
  if(d.asstgo){S.asst={step:1,obj:d.asstgo,dias:null,min:null};S.plan=null;go("assist");return}
  if(d.asst){const [k,v]=d.asst.split(".");S.asst[k]=k==="obj"?v:+v;render();return}
  if(d.detg){const [k,g]=d.detg.split(".");const a=S.det.g[k]||(S.det.g[k]=[]);const i=a.indexOf(g);i<0?a.push(g):a.splice(i,1);render();return}
  if(d.how){S.edx=null;S.how=d.how;S.sheet="how";render();return}
  if(d.mus!==undefined){S.musSel=(S.musSel===d.mus||!d.mus)?null:d.mus;render();return}
  if(d.evo){S.evo=d.evo;render();return}
  const a=d.act;
  if(a.startsWith("toast:")){toast(a.slice(6));return}
  if(a.startsWith("eds:")){A.eds(a.slice(4));return}
  (A[a]||(()=>{}))();
});
$("#app").addEventListener("input",e=>{
  const t=e.target;
  if(t.dataset.cad){S.cadDraft[t.dataset.cad]=t.value}
  if(t.id==="notat"&&S.nota){S.nota.texto=t.value}
  if(t.id==='admq'){S.admQ=t.value;const l=$('#admlist');if(l)l.innerHTML=admRows()}
  if(t.dataset.kg){const [i,j]=t.dataset.kg.split(".").map(Number);S.w.ex[i].sets[j].kg=+t.value||0}
  if(t.dataset.r){const [i,j]=t.dataset.r.split(".").map(Number);S.w.ex[i].sets[j].r=+t.value||0}
  if(t.dataset.ci!==undefined&&t.value){const n=document.querySelector(`[data-ci='${+t.dataset.ci+1}']`);n&&n.focus()}
  if(t.dataset.foco){FICHAS[t.dataset.foco].foco=t.textContent.trim()||"Ficha"}
});


/* ================= App real: conta, dados no celular, sincronização e presença ================= */
const APPV=(window.APP_CONFIG||{}).VERSION||"1.0";
const SB=supabase.createClient(APP_CONFIG.SUPABASE_URL,APP_CONFIG.SUPABASE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:"pkce"}});
const DW=["dom","seg","ter","qua","qui","sex","sáb"];
const p2=n=>String(n).padStart(2,"0");
function hm(d){d=new Date(d);return p2(d.getHours())+":"+p2(d.getMinutes())}
function dm(d){d=new Date(d);return p2(d.getDate())+"/"+p2(d.getMonth()+1)}
const cap=t=>t.charAt(0).toUpperCase()+t.slice(1);
function hojeTxt(){return cap(new Date().toLocaleDateString("pt-BR",{weekday:"long",day:"numeric",month:"long"}))}
function diaCurto(x){const d=new Date(x),t=new Date(),y=new Date();y.setDate(t.getDate()-1);
  if(d.toDateString()===t.toDateString())return "Hoje";if(d.toDateString()===y.toDateString())return "Ontem";
  return cap(d.toLocaleDateString("pt-BR",{weekday:"short",day:"numeric",month:"short"}).replace(/\./g,""))}
function esc(x){return String(x??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]))}
function uuid(){if(crypto.randomUUID)return crypto.randomUUID();const b=crypto.getRandomValues(new Uint8Array(16));b[6]=b[6]&15|64;b[8]=b[8]&63|128;const h=[...b].map(x=>x.toString(16).padStart(2,"0")).join("");return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`}
async function sha(t){const b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(t));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("")}
function semana(){const t=new Date();t.setHours(0,0,0,0);const dow=(t.getDay()+6)%7,mon=new Date(t);mon.setDate(t.getDate()-dow);
  return ["S","T","Q","Q","S","S","D"].map((l,i)=>{const d=new Date(mon);d.setDate(mon.getDate()+i);const ok=HIST.some(h=>new Date(h.at).toDateString()===d.toDateString());return [l,String(d.getDate()),ok?1:0,i===dow?1:0]})}
function calcEvo(){EVO={};EVO_D={};[...HIST].reverse().forEach(h=>(h.items||[]).forEach(it=>{if(it.u&&it.u!=="rep")return;const mx=Math.max(0,...it.sets.map(x=>+x.kg||0));if(!mx)return;
  (EVO[it.n]=EVO[it.n]||[]).push(mx);(EVO_D[it.n]=EVO_D[it.n]||[]).push(dm(h.at))}))}
function qrUrl(code){return location.origin+location.pathname.replace(/index\.html$/,"")+"?qr="+code}
function qrImg(text){const q=qrcode(0,"M");q.addData(text);q.make();return q.createSvgTag({cellSize:4,margin:2,scalable:true})}

/* ---------- dados guardados no celular ---------- */
const LSK=()=>"cocta:"+(S.user?S.user.id:"anon"),QK=()=>"cocta:q:"+(S.user?S.user.id:"anon");
function snapshot(){return {cad:S.cad,FICHAS,ORDER,HIST,lastDone:S.lastDone,off:S.off,offList:S.offList,modeDef:S.modeDef,notif:S.notif,presOnly:S.presOnly,boneco:S.boneco,inAt:S.inAt,limite:S.limite,myPres:S.myPres,qrHash:S.qrHash,admin:S.admin,configured:S.configured}}
function persist(){if(!S.user||!S.ready)return;try{localStorage.setItem(LSK(),JSON.stringify(snapshot()))}catch(e){}perfilChanged()}
function loadLocal(){try{const d=JSON.parse(localStorage.getItem(LSK())||"null");if(!d)return false;
  if(d.FICHAS&&Object.keys(d.FICHAS).length){FICHAS=d.FICHAS;ORDER=(d.ORDER&&d.ORDER.length)?d.ORDER:Object.keys(FICHAS)}if(d.HIST)HIST=d.HIST;
  ["cad","lastDone","off","offList","modeDef","notif","presOnly","boneco","inAt","limite","myPres","qrHash","admin","configured"].forEach(k=>{if(d[k]!==undefined)S[k]=d[k]});
  S.mode=S.modeDef;S.today=sug();return true}catch(e){return false}}
function resetLocal(){S.cad=null;FICHAS=JSON.parse(JSON.stringify(STD));ORDER=["A","B","C"];HIST=[];S.inAt=null;S.limite=null;S.myPres=[];S.lastDone="C";S.today="A";S.off=0;S.offList=[];S.presOnly=false;S.configured=false;S.admin=false;S.qrHash=null;S.modeDef="direto";S.w=null;S.ok=null;S.ask2h=false;lastPerfil=""}

/* ---------- fila de envio (funciona sem internet) ---------- */
function qget(){try{return JSON.parse(localStorage.getItem(QK())||"[]")}catch(e){return []}}
function qset(q){try{localStorage.setItem(QK(),JSON.stringify(q))}catch(e){}}
function qpush(op){const q=qget();if(op.t==="perfil"&&q.some(o=>o.t==="perfil"))return;q.push(op);qset(q)}
function perfilRow(){const c=S.cad||{};return {id:S.user.id,nome:c.nome||"",posto:c.posto||null,vinculo:c.vinc==="dep"?"dependente":"socio",titular:c.vinc==="dep"?(c.titular||null):null,celular:c.tel||null,boneco:c.boneco||S.boneco||"m",uso:S.presOnly?"presenca":"treino",modo_treino:S.modeDef,
  dados:{FICHAS,ORDER,lastDone:S.lastDone,off:S.off,offList:S.offList,notif:S.notif,configured:!!S.configured}}}
let lastPerfil="";
function perfilChanged(){if(!S.cad||!S.user)return;const j=JSON.stringify(perfilRow());if(j===lastPerfil)return;lastPerfil=j;qpush({t:"perfil"});clearTimeout(perfilChanged.h);perfilChanged.h=setTimeout(flush,1500)}
const netErr=e=>!navigator.onLine||!e||!e.code||/fetch|network|JWT/i.test(e.message||"");
let flushing=false;
async function flush(){if(flushing||!S.user||!navigator.onLine)return;flushing=true;
  try{let q=qget();while(q.length){const r=await runOp(q[0]);if(r==="retry")break;q=qget();q.shift();qset(q)}}finally{flushing=false}}
async function runOp(op){
  try{let res;
    if(op.t==="perfil"){if(!S.cad)return "ok";res=await SB.from("perfis").upsert(perfilRow())}
    else if(op.t==="treino"){const h=op.h;res=await SB.from("treinos").upsert({id:h.id,user_id:S.user.id,letra:h.f,feito_em:h.at,itens:{min:h.min,s:h.s,vol:h.vol,items:h.items}})}
    else if(op.t==="in")res=await SB.rpc("registrar_entrada_v2",{p_codigo:op.code,p_hora:op.hora,p_agora:new Date().toISOString()});
    else if(op.t==="out")res=await SB.rpc("registrar_saida_v2",{p_hora:op.hora,p_agora:new Date().toISOString()});
    else if(op.t==="still")res=await SB.rpc("ainda_treinando");
    else if(op.t==="nota")res=await SB.from("notas_teste").insert(op.n);
    if(res&&res.error){const e=res.error;
      if(op.t==="in"&&/qr_invalido/.test(e.message||"")){if(S.inAt===op.hora){S.inAt=null;S.limite=null;S.myPres=S.myPres.filter(p=>p.entrada!==op.hora);persist();render();toast("QR code não reconhecido. Faça o check-in de novo.")}return "ok"}
      if(netErr(e))return "retry";console.warn("sync",op.t,e);return "ok"}
    return "ok"}catch(e){return "retry"}}

/* ---------- busca os dados da conta ---------- */
async function pull(){if(!navigator.onLine||!S.user)return;const uid=S.user.id,pend=qget();
  const [p,t,pr,qh]=await Promise.all([SB.from("perfis").select("*").eq("id",uid).maybeSingle(),
    SB.from("treinos").select("id,letra,feito_em,itens").eq("user_id",uid).order("feito_em",{ascending:false}).limit(300),
    SB.from("presencas").select("id,entrada,saida,limite_saida,saida_auto").eq("user_id",uid).order("entrada",{ascending:false}).limit(30),
    SB.rpc("qr_hash")]);
  if(p.error&&netErr(p.error))return;
  if(p.data){S.admin=!!p.data.is_admin;
    if(!pend.some(o=>o.t==="perfil")){const r=p.data,d=r.dados||{};
      S.cad={nome:r.nome||"",posto:r.posto||"",vinc:r.vinculo==="dependente"?"dep":"socio",titular:r.titular||"",tel:r.celular||"",boneco:r.boneco||"m"};S.boneco=S.cad.boneco;
      S.presOnly=r.uso==="presenca";S.modeDef=r.modo_treino||"direto";S.mode=S.modeDef;
      if(d.FICHAS&&Object.keys(d.FICHAS).length){FICHAS=d.FICHAS;ORDER=(d.ORDER&&d.ORDER.length)?d.ORDER:Object.keys(FICHAS)}
      ["lastDone","off","offList","notif","configured"].forEach(k=>{if(d[k]!==undefined)S[k]=d[k]});lastPerfil=JSON.stringify(perfilRow())}}
  if(t.data){const have=new Set(HIST.map(h=>h.id));t.data.forEach(r=>{if(have.has(r.id))return;const it=r.itens||{};HIST.push({id:r.id,at:r.feito_em,f:r.letra,min:it.min||0,s:it.s||0,vol:it.vol||0,items:it.items||[]})});
    HIST.sort((a,b)=>new Date(b.at)-new Date(a.at))}
  if(pr.data&&!pend.some(o=>["in","out","still"].includes(o.t))){S.myPres=pr.data;const open=pr.data.find(x=>!x.saida);
    if(open){S.inAt=open.entrada;S.limite=open.limite_saida}else{S.inAt=null;S.limite=null;S.ask2h=false}}
  if(qh.data)S.qrHash=qh.data;
  S.today=sug();persist()}

/* ---------- entrada no app ---------- */
async function boot(){
  const u=new URL(location.href),qr=u.searchParams.get("qr");
  if(qr){try{sessionStorage.setItem("cocta:qr",qr)}catch(e){}u.searchParams.delete("qr");history.replaceState(null,"",u.pathname+u.search+u.hash)}
  let session=null;try{session=(await SB.auth.getSession()).data.session}catch(e){}
  SB.auth.onAuthStateChange((ev,ses)=>{if(ses&&ses.user&&(!S.user||S.user.id!==ses.user.id))setTimeout(()=>startSession(ses.user),0)});
  if(session)return startSession(session.user);
  let last=null;try{last=JSON.parse(localStorage.getItem("cocta:user")||"null")}catch(e){}
  if(last&&!navigator.onLine)return startSession(last);
  go("entrar")}
async function startSession(user){
  if(startSession.uid===user.id)return;startSession.uid=user.id;S.ready=false;
  S.user={id:user.id,email:user.email,nome:(user.user_metadata&&(user.user_metadata.full_name||user.user_metadata.name))||""};
  try{localStorage.setItem("cocta:user",JSON.stringify({id:S.user.id,email:S.user.email,user_metadata:{full_name:S.user.nome}}))}catch(e){}
  S.screen="carregando";render();resetLocal();loadLocal();S.ready=true;
  try{await pull()}catch(e){}
  flush();route()}
function route(){
  if(!S.cad){S.cadEdit=false;S.cadDraft={nome:S.user.nome||"",posto:"",vinc:"socio",titular:"",tel:"",boneco:"m"};go("cadastro");return}
  if(!S.configured){S.montarAgain=false;go("montar");return}
  go("hoje");pendingQR()}
function pendingQR(){let qr=null;try{qr=sessionStorage.getItem("cocta:qr");sessionStorage.removeItem("cocta:qr")}catch(e){}
  if(!qr||!S.cad)return;onQR(qrUrl(qr))}

/* ---------- leitura do QR code pela câmera ---------- */
let scanStream=null,scanTimer=null,detector=null;
async function startScan(){
  if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){S.scanMsg="Este navegador não abre a câmera. Use a câmera do celular no QR code.";render();return}
  try{scanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"environment"},audio:false})}catch(e){S.scanMsg="Libere o acesso à câmera para ler o QR code.";render();return}
  if(!S.scan){stopScan();return}attachVideo();
  detector=null;if("BarcodeDetector" in window){try{detector=new BarcodeDetector({formats:["qr_code"]})}catch(e){}}
  const cv=document.createElement("canvas"),cx=cv.getContext("2d",{willReadFrequently:true});
  const tick=async()=>{if(!S.scan||!scanStream)return;const v=$("#qrv");
    try{if(v&&v.readyState>=2){let txt=null;
      if(detector){const r=await detector.detect(v);if(r&&r[0])txt=r[0].rawValue}
      else{const w=v.videoWidth,h=v.videoHeight,k=Math.min(1,640/Math.max(w,h));cv.width=Math.round(w*k);cv.height=Math.round(h*k);cx.drawImage(v,0,0,cv.width,cv.height);
        const im=cx.getImageData(0,0,cv.width,cv.height),r=jsQR(im.data,im.width,im.height,{inversionAttempts:"dontInvert"});if(r)txt=r.data}
      if(txt&&await onQR(txt))return}}catch(e){}
    scanTimer=setTimeout(tick,200)};
  tick()}
function attachVideo(){const v=$("#qrv");if(v&&scanStream&&v.srcObject!==scanStream){v.srcObject=scanStream;v.play().catch(()=>{})}}
function stopScan(){clearTimeout(scanTimer);if(scanStream)scanStream.getTracks().forEach(t=>t.stop());scanStream=null}
function codeFrom(txt){txt=(txt||"").trim();try{return new URL(txt).searchParams.get("qr")}catch(e){return /^[0-9a-f]{24}$/i.test(txt)?txt:null}}
async function onQR(txt){const code=codeFrom(txt);
  const bad=()=>{S.scanMsg="Este não é o QR code da academia.";if(S.scan)render();else toast(S.scanMsg);return false};
  if(!code)return bad();
  if(S.qrHash&&await sha(code)!==S.qrHash){if(!navigator.onLine)return bad();
    try{const {data}=await SB.rpc("qr_hash");if(data)S.qrHash=data}catch(e){}if(await sha(code)!==S.qrHash)return bad()}
  if(S.inAt){stopScan();S.scan=false;S.scanMsg="";
    if(Date.now()-new Date(S.inAt).getTime()<5*60000){render();toast("Check-in já feito às "+hm(S.inAt));return true}
    doCheckout();return true}
  stopScan();S.scan=false;S.scanMsg="";const hora=new Date();S.inAt=hora.toISOString();S.limite=new Date(hora.getTime()+7200000).toISOString();S.ask2h=false;
  S.myPres.unshift({entrada:S.inAt,saida:null});qpush({t:"in",code,hora:S.inAt});S.ok={k:"in"};persist();render();flush();return true}

/* ---------- tempo na academia: pergunta depois do limite ---------- */
function checkLimite(){if(S.inAt&&S.limite&&!S.ask2h&&!S.scan&&Date.now()>new Date(S.limite).getTime()){S.ask2h=true;beep();render()}}
setInterval(checkLimite,20000);
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible"&&S.user){checkLimite();flush()}});
addEventListener("online",()=>{if(S.user){flush().then(()=>pull()).then(()=>render()).catch(()=>{})}else render()});
addEventListener("offline",()=>render());

/* ---------- administração ---------- */
async function loadAdmin(){S.admLoading=true;render();const t=new Date();t.setHours(0,0,0,0);let de=new Date(t),ate=new Date(t);ate.setDate(ate.getDate()+1);
  if(S.admDay==="ontem"){de.setDate(de.getDate()-1);ate.setDate(ate.getDate()-1)}if(S.admDay==="semana")de.setDate(de.getDate()-6);
  try{const [r,q]=await Promise.all([SB.rpc("presencas_admin_v2",{p_de:de.toISOString(),p_ate:ate.toISOString()}),S.admQR?Promise.resolve({data:S.admQR}):SB.rpc("qr_atual")]);
    if(r.error)throw r.error;S.admRows=r.data||[];if(q.data)S.admQR=q.data}catch(e){toast("Sem conexão. Tente de novo.")}
  S.admLoading=false;render()}

/* ---------- notas do piloto (só no modo teste) ---------- */
const MODO_TESTE=(window.APP_CONFIG||{}).AUTH_MODE==="teste";
const TELAS={hoje:"Hoje",treino:"Treino em andamento",fichas:"Minhas fichas",ficha:"Editar ficha",historico:"Histórico",perfil:"Perfil",cadastro:"Cadastro",admin:"Administração",montar:"Monte seu treino",assist:"Modo assistente",detalhe:"Planeje em detalhes",entrar:"Entrar",carregando:"Carregando"};
function telaAtual(){let t=TELAS[S.screen]||S.screen;if(S.scan)t+=" · leitura do QR";else if(S.ask2h)t+=" · confirmar saída";else if(S.ok)t+=S.ok.k==="in"?" · check-in feito":" · treino finalizado";else if(S.sheet)t+=" · janela "+S.sheet;return t}
function notaView(){
  if(!MODO_TESTE||!S.user)return"";
  if(!S.nota)return `<button class="nota-fab" data-act="nota" aria-label="Anotar">${ic("edit")}</button>`;
  const N=S.nota;
  return `<div class="dim" data-dim="notaclose"><div class="sheet"><div class="wrap"><div class="grab"></div>
    <div class="row" style="align-items:flex-start"><h2 class="sp">Anotar</h2><button class="mini" data-act="notaclose" aria-label="Fechar">${ic("x")}</button></div>
    <p class="muted" style="margin:0 0 10px;font-size:14px">Tela: <b>${esc(N.tela)}</b></p>
    <textarea id="notat" class="inp" rows="5" style="height:auto;min-height:120px;padding:12px;resize:vertical" placeholder="O que está estranho, errado ou poderia ser melhor?">${esc(N.texto||"")}</textarea>
    <button class="li" data-act="notaprint" style="width:100%;margin:10px 0;border:0;background:none;display:flex;gap:10px;align-items:center;padding:6px 0;text-align:left"><span class="sw ${N.comPrint?'on':''}" style="flex:none"></span><span class="sp">Anexar foto desta tela${N.print===undefined?" (preparando…)":N.print===null?" (indisponível)":""}</span></button>
    <button class="btn red" data-act="notasave">Salvar nota</button>
  </div></div></div>`}
function abrirNota(){S.nota={tela:telaAtual(),texto:"",comPrint:true,print:undefined};
  const cap=()=>window.html2canvas($("#screen"),{scale:Math.min(1,600/$("#screen").offsetWidth),logging:false,useCORS:true,backgroundColor:"#ffffff"})
    .then(c=>{if(S.nota){S.nota.print=c.toDataURL("image/jpeg",0.6);render();const t=$("#notat");if(t){t.focus();t.selectionStart=t.value.length}}})
    .catch(()=>{if(S.nota){S.nota.print=null;render()}});
  // capture before the sheet is drawn, so the photo shows the screen itself
  const go=()=>{cap();setTimeout(()=>{if(S.nota&&S.nota.print===undefined)render()},30)};
  if(window.html2canvas)go();else{const sc=document.createElement("script");sc.src="vendor/html2canvas.min.js";sc.onload=go;sc.onerror=()=>{S.nota.print=null;render()};document.head.appendChild(sc)}
}
function salvarNota(){const N=S.nota,t=$("#notat"),texto=((t&&t.value)||N.texto||"").trim();if(!texto)return toast("Escreva a nota");
  const n={id:uuid(),user_id:S.user.id,autor:S.cad?fullName():null,tela:N.tela,texto,aparelho:`${navigator.userAgent} · ${innerWidth}×${innerHeight}`,print:N.comPrint&&N.print?N.print:null,criado_em:new Date().toISOString()};
  qpush({t:"nota",n});S.nota=null;render();flush();toast("Nota salva ✓")}

renderBench();boot();
